/projects/{projectId}/eval-runs {
  "post": {
    "operationId": "createEvalRun",
    "tags": [
      "Eval runs"
    ],
    "summary": "Create an eval run (async)",
    "description": "Creates a suite run from an existing `suiteId` (rerun) and/or inline `tests`, then **detaches execution and responds `202` immediately** with the `runId`. Validation and quota errors surface on this request; poll `GET /eval-runs/{runId}` for progress. The run appears live in the hosted UI Runs tab, tagged `source: \"api\"`.\n\nA bare `suiteId` with no inline tests reruns the suite as configured. Per-organization concurrency is capped (default 2 concurrent runs); exceeding it returns `429` with `details.reason: \"CONCURRENT_RUN_LIMIT\"`.\n\nFor a suite with attached project environments, pass `environmentId` to choose which one the run uses; the `202` echoes the resolved `environment` triple, and `GET /eval-runs/{runId}` reports the same triple for the life of the run.\n\nTo make the run readable as something more specific than `API` in the Runs table, send `x-mcpjam-launcher` (and `x-mcpjam-ci` from a CI job). Both are labels: `source` is stamped `api` either way.",
    "parameters": [
      {
        "$ref": "#/components/parameters/evalVocabularyHeader"
      },
      {
        "$ref": "#/components/parameters/projectId"
      },
      {
        "$ref": "#/components/parameters/launcherHeader"
      },
      {
        "$ref": "#/components/parameters/ciHeader"
      }
    ],
    "requestBody": {
      "required": true,
      "content": {
        "application/json": {
          "schema": {
            "$ref": "#/components/schemas/EvalRunCreateRequest"
          },
          "example": {
            "suiteName": "smoke",
            "serverIds": [
              "srv_abc123"
            ],
            "tests": [
              {
                "title": "echo works",
                "runs": 1,
                "model": "anthropic/claude-haiku-4.5",
                "provider": "anthropic",
                "steps": [
                  {
                    "id": "s1",
                    "kind": "prompt",
                    "prompt": "Use the echo tool to say hi"
                  },
                  {
                    "id": "s2",
                    "kind": "assert",
                    "assertion": {
                      "type": "toolCalledWith",
                      "toolName": "echo",
                      "args": {
                        "args": {
                          "text": "hi"
                        }
                      }
                    }
                  }
                ]
              }
            ]
          }
        }
      }
    },
    "responses": {
      "202": {
        "description": "Run created; execution continues in the background.",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/EvalRunCreated"
            },
            "example": {
              "runId": "run_abc123",
              "suiteId": "suite_def456",
              "status": "running",
              "caseUpsert": {
                "committed": [
                  {
                    "name": "echo works"
                  }
                ],
                "failed": []
              },
              "environment": null
            }
          }
        }
      },
      "400": {
        "$ref": "#/components/responses/ValidationError"
      },
      "401": {
        "$ref": "#/components/responses/Unauthorized"
      },
      "403": {
        "$ref": "#/components/responses/Forbidden"
      },
      "404": {
        "$ref": "#/components/responses/NotFound"
      },
      "429": {
        "$ref": "#/components/responses/RateLimited"
      },
      "500": {
        "$ref": "#/components/responses/InternalError"
      },
      "502": {
        "$ref": "#/components/responses/ServerUnreachable"
      },
      "504": {
        "$ref": "#/components/responses/Timeout"
      }
    }
  }
}
/projects/{projectId}/eval-suites {
  "get": {
    "operationId": "listEvalSuites",
    "tags": [
      "Catalog"
    ],
    "summary": "List a project's eval suites",
    "description": "Eval suites in the project with latest-run summaries and pass-rate trends \u2014 the `suiteId`s the eval-run routes take.",
    "parameters": [
      {
        "$ref": "#/components/parameters/evalVocabularyHeader"
      },
      {
        "$ref": "#/components/parameters/projectId"
      }
    ],
    "responses": {
      "200": {
        "description": "The project's eval suites.",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/EvalSuitePage"
            }
          }
        }
      },
      "401": {
        "$ref": "#/components/responses/Unauthorized"
      },
      "403": {
        "$ref": "#/components/responses/Forbidden"
      },
      "404": {
        "$ref": "#/components/responses/NotFound"
      },
      "429": {
        "$ref": "#/components/responses/RateLimited"
      },
      "500": {
        "$ref": "#/components/responses/InternalError"
      },
      "502": {
        "$ref": "#/components/responses/ServerUnreachable"
      }
    }
  },
  "post": {
    "operationId": "createEvalSuite",
    "tags": [
      "Eval runs"
    ],
    "summary": "Create an eval suite (author-only, does not run)",
    "description": "Creates a runnable eval suite \u2014 the suite record plus its test cases \u2014 and responds `201` **synchronously**, WITHOUT executing anything. Use this to author a suite, then run it later with `POST /eval-runs` (passing the returned `suiteId`).\n\nThis is distinct from `POST /eval-runs`, which creates a run and **detaches execution**, responding `202` with a `runId`. There is no concurrency cap here (no run is started).\n\nThe body uses an ergonomic authoring shape: a suite-level default `model` (and optional `provider`) applies to every test unless the test overrides it; `provider` is derived from a `provider/model` id when neither is supplied. Each test's case body is an ordered `steps` array (prompt / toolCall / interact / assert).\n\nGuest callers are denied (suite creation is a write).",
    "parameters": [
      {
        "$ref": "#/components/parameters/evalVocabularyHeader"
      },
      {
        "$ref": "#/components/parameters/projectId"
      }
    ],
    "requestBody": {
      "required": true,
      "content": {
        "application/json": {
          "schema": {
            "$ref": "#/components/schemas/EvalSuiteCreateRequest"
          },
          "example": {
            "name": "smoke",
            "serverIds": [
              "srv_abc123"
            ],
            "model": "anthropic/claude-haiku-4.5",
            "tests": [
              {
                "title": "lists files",
                "steps": [
                  {
                    "id": "s1",
                    "kind": "prompt",
                    "prompt": "List the files in the project root."
                  },
                  {
                    "id": "s2",
                    "kind": "assert",
                    "assertion": {
                      "type": "toolCalledWith",
                      "toolName": "list_files",
                      "args": {
                        "args": {}
                      }
                    }
                  }
                ]
              }
            ]
          }
        }
      }
    },
    "responses": {
      "201": {
        "description": "The suite was created.",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/EvalSuiteCreated"
            }
          }
        }
      },
      "400": {
        "$ref": "#/components/responses/ValidationError"
      },
      "401": {
        "$ref": "#/components/responses/Unauthorized"
      },
      "403": {
        "$ref": "#/components/responses/Forbidden"
      },
      "404": {
        "$ref": "#/components/responses/NotFound"
      },
      "429": {
        "$ref": "#/components/responses/RateLimited"
      },
      "500": {
        "$ref": "#/components/responses/InternalError"
      },
      "502": {
        "$ref": "#/components/responses/ServerUnreachable"
      }
    }
  }
}
